// Generated by ng-openapi-mock. Changes here are lost on the next run.
import { HttpInterceptorFn, HttpRequest, HttpResponse } from '@angular/common/http';
import { delay, of, tap } from 'rxjs';
import { MOCK_API_DELAY_MS, MOCK_API_LOG, MOCK_API_ROUTES, type MockApiRoute } from './mock-api.data';
import { MOCK_API_OVERRIDES } from './mock-api.overrides';

// Mocked calls never reach the network, so they are logged to the browser
// console instead: one collapsed group per call, written when the response arrives.
function logCall(req: HttpRequest<unknown>, res: HttpResponse<unknown>, route: MockApiRoute, overridden: boolean, startedAt: number): void {
  const ms = Math.round(performance.now() - startedAt);
  const source = overridden ? 'override' : 'generated';
  console.groupCollapsed(
    `%c[mock]%c ${req.method} ${req.urlWithParams} → ${res.status} %c${route.id} (${source}, ${ms} ms)`,
    'color: #8e44ad; font-weight: bold',
    'color: inherit',
    'color: gray',
  );
  if (req.body != null) {
    console.log('request body', req.body);
  }
  console.log('response body', res.body);
  console.groupEnd();
}

const mockResponses: HttpInterceptorFn = (req, next) => {
  const pathname = new URL(req.url, 'http://localhost').pathname;
  const route = MOCK_API_ROUTES.find((r) => r.method === req.method && new RegExp(r.pattern).test(pathname));
  if (!route) {
    return next(req);
  }
  const startedAt = performance.now();
  const overridden = Object.prototype.hasOwnProperty.call(MOCK_API_OVERRIDES, route.id);
  const data = overridden ? MOCK_API_OVERRIDES[route.id] : route.body;
  // Endpoints without a body answer 204, unless an override gives them one.
  const status = overridden && route.status === 204 ? 200 : route.status;
  const body = route.kind === 'blob' ? new Blob([]) : data == null ? null : structuredClone(data);
  const response = new HttpResponse({ status, body, url: req.url });
  return of(response).pipe(
    delay(MOCK_API_DELAY_MS),
    tap(() => MOCK_API_LOG && logCall(req, response, route, overridden, startedAt)),
  );
};

/**
 * Answers API calls with generated mock data. Requests without a mock pass
 * through unchanged. Register it in app.config.ts:
 *   provideHttpClient(withInterceptors([mockApiInterceptor]))
 *
 * Only active in development mode (ng serve, development builds). Production
 * builds replace ngDevMode with false, so every request passes through and
 * the mock data is left out of the bundle.
 */
export const mockApiInterceptor: HttpInterceptorFn =
  typeof ngDevMode !== 'undefined' && !ngDevMode ? (req, next) => next(req) : mockResponses;
